import { test, expect } from '@playwright/test';

test.describe('Filter list by multiple statuses', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
    // Wait for the list to load
    await page.waitForLoadState('networkidle');
  });

  test('should display all items when no filters are applied', async ({ page }) => {
    // Verify that the list is visible
    const listItems = page.getByRole('listitem');
    const initialCount = await listItems.count();
    expect(initialCount).toBeGreaterThan(0);
  });

  test('should filter list by single status', async ({ page }) => {
    // Click on the status filter dropdown
    const statusFilter = page.getByRole('button', { name: /status/i });
    await statusFilter.click();

    // Select "Active" status
    const activeOption = page.getByRole('option', { name: /active/i });
    await activeOption.click();

    // Verify that only active items are displayed
    const listItems = page.getByRole('listitem');
    const items = await listItems.all();

    for (const item of items) {
      const statusBadge = item.getByText(/active/i);
      await expect(statusBadge).toBeVisible();
    }
  });

  test('should filter list by multiple statuses simultaneously', async ({ page }) => {
    // Click on the status filter dropdown
    const statusFilter = page.getByRole('button', { name: /status/i });
    await statusFilter.click();

    // Select "Active" status
    const activeOption = page.getByRole('option', { name: /active/i });
    await activeOption.click();

    // Keep dropdown open and select "Pending" status
    const pendingOption = page.getByRole('option', { name: /pending/i });
    await pendingOption.click();

    // Verify that items with either Active or Pending status are displayed
    const listItems = page.getByRole('listitem');
    const items = await listItems.all();

    expect(items.length).toBeGreaterThan(0);

    for (const item of items) {
      const statusText = await item.textContent();
      const hasActiveOrPending = /active|pending/i.test(statusText || '');
      expect(hasActiveOrPending).toBeTruthy();
    }
  });

  test('should update list when adding another status filter', async ({ page }) => {
    // Get initial count with no filters
    const initialItems = page.getByRole('listitem');
    const initialCount = await initialItems.count();

    // Click on the status filter dropdown
    const statusFilter = page.getByRole('button', { name: /status/i });
    await statusFilter.click();

    // Select "Active" status
    const activeOption = page.getByRole('option', { name: /active/i });
    await activeOption.click();

    // Get count after first filter
    const afterFirstFilter = page.getByRole('listitem');
    const countAfterFirst = await afterFirstFilter.count();

    // Keep dropdown open and select "Completed" status
    const completedOption = page.getByRole('option', { name: /completed/i });
    await completedOption.click();

    // Get count after second filter
    const afterSecondFilter = page.getByRole('listitem');
    const countAfterSecond = await afterSecondFilter.count();

    // Verify that adding another filter changes the result count
    expect(countAfterSecond).toBeGreaterThanOrEqual(countAfterFirst);
    expect(countAfterSecond).toBeLessThanOrEqual(initialCount);
  });

  test('should clear all status filters and show all items', async ({ page }) => {
    // Click on the status filter dropdown
    const statusFilter = page.getByRole('button', { name: /status/i });
    await statusFilter.click();

    // Select multiple statuses
    const activeOption = page.getByRole('option', { name: /active/i });
    await activeOption.click();

    const pendingOption = page.getByRole('option', { name: /pending/i });
    await pendingOption.click();

    // Click clear filters button
    const clearButton = page.getByRole('button', { name: /clear/i });
    await clearButton.click();

    // Verify that all items are displayed again
    const listItems = page.getByRole('listitem');
    const items = await listItems.all();
    expect(items.length).toBeGreaterThan(0);

    // Verify that the filter dropdown shows no selections
    const statusFilterButton = page.getByRole('button', { name: /status/i });
    const filterText = await statusFilterButton.textContent();
    expect(filterText).not.toContain('Active');
    expect(filterText).not.toContain('Pending');
  });
});
